 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    supports = [{c for c, v in enumerate(row) if v != bg} for row in grid]

    # A repeated row can be a damaged/occluded copy of another row: where
    # the smaller pattern matches a larger one exactly, mark the omitted cells.
    for r in range(h):
        sr = supports[r]
        if not sr:
            continue
        best = None
        for q in range(h):
            if q == r:
                continue
            sq = supports[q]
            if len(sq) <= len(sr) or not sr.issubset(sq):
                continue
            if any(grid[r][c] != grid[q][c] for c in sr):
                continue
            # Prefer the closest larger matching row; ties are harmless.
            extra = len(sq) - len(sr)
            if best is None or extra < best[0]:
                best = (extra, q)
        if best is not None:
            q = best[1]
            for c in supports[q] - sr:
                out[r][c] = 1
    return out
